from collections import Counter

class Solution:
    def longestCommonSubsequence(self, arrays: list[list[int]]) -> list[int]:
        counts = Counter()
        for arr in arrays:
            counts.update(arr)
        n = len(arrays)
        return [x for x in sorted(counts) if counts[x] == n]

class Solution {
public:
    vector<int> longestCommonSubsequence(vector<vector<int>>& arrays) {
        unordered_map<int, int> counts;
        for (auto& arr : arrays) {
            for (int x : arr) counts[x]++;
        }
        int n = arrays.size();
        vector<int> ans;
        for (int x : arrays[0]) {
            if (counts[x] == n) ans.push_back(x);
        }
        return ans;
    }
};

class Solution {
    public java.util.List<Integer> longestCommonSubsequence(int[][] arrays) {
        int[] counts = new int[101];
        for (int[] arr : arrays) {
            for (int x : arr) counts[x]++;
        }
        int n = arrays.length;
        java.util.List<Integer> ans = new java.util.ArrayList<>();
        for (int x = 1; x <= 100; x++) {
            if (counts[x] == n) ans.add(x);
        }
        return ans;
    }
}

var longestCommonSubsequence = function(arrays) {
  const counts = new Map();
  for (const arr of arrays) {
    for (const x of arr) {
      counts.set(x, (counts.get(x) || 0) + 1);
    }
  }
  const n = arrays.length;
  const ans = [];
  for (const x of arrays[0]) {
    if (counts.get(x) === n) ans.push(x);
  }
  return ans;
};
